package com.mohymods.kingdomsmp.profession;
import net.minecraft.nbt.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class FarmerEvidenceTest {
 @TempDir Path dir;
 final UUID player=UUID.randomUUID();
 @Test void uniqueSoilAndOffspringCannotBeCreditedAgainAcrossBandsOrReload(){var e=new FarmerEvidence();assertTrue(e.record(player,ProfessionRank.APPRENTICE,"soil",1,"overworld/123"));assertFalse(e.record(player,ProfessionRank.APPRENTICE,"soil",1,"overworld/123"));assertTrue(e.record(player,ProfessionRank.APPRENTICE,"cow",1,"child-1"));var restored=FarmerEvidence.load(e.save());assertFalse(restored.record(player,ProfessionRank.JOURNEYMAN,"cow",1,"child-1"));assertEquals(1,restored.count(player,ProfessionRank.APPRENTICE,"cow"));assertEquals(0,restored.count(player,ProfessionRank.JOURNEYMAN,"cow"));}
 @Test void stageCountersRemainSeparateAndSaturate(){var e=new FarmerEvidence();for(int n=0;n<250;n++)e.record(player,ProfessionRank.APPRENTICE,"wheat",4096,null);assertEquals(FarmerEvidence.MAX_COUNTER,e.count(player,ProfessionRank.APPRENTICE,"wheat"));assertFalse(e.record(player,ProfessionRank.APPRENTICE,"wheat",1,null));assertEquals(0,e.count(player,ProfessionRank.JOURNEYMAN,"wheat"));}
 @Test void malformedStateFailsClosed(){var e=new FarmerEvidence();e.record(player,ProfessionRank.APPRENTICE,"soil",1,"overworld/123");var data=e.save();data.getList("players",Tag.TAG_COMPOUND).getCompound(0).getCompound("counters").putInt("apprentice/forged",100);assertThrows(IllegalArgumentException.class,()->FarmerEvidence.load(data));var future=e.save();future.putInt("schema",2);assertThrows(IllegalArgumentException.class,()->FarmerEvidence.load(future));}
 @Test void boundedEvidenceDoesNotEvictOldIdentities(){var e=new FarmerEvidence();for(int n=0;n<FarmerEvidence.MAX_UNIQUE;n++)assertTrue(e.record(player,ProfessionRank.APPRENTICE,"soil",1,"cell"+n));assertFalse(e.record(player,ProfessionRank.APPRENTICE,"soil",1,"newcell"));assertFalse(e.record(player,ProfessionRank.APPRENTICE,"soil",1,"cell0"));assertEquals(FarmerEvidence.MAX_UNIQUE,e.count(player,ProfessionRank.APPRENTICE,"soil"));}
 @Test void farmerCatalogContainsOnlyApproved24AndFinalInspectionNeedsPriorMasterTrials(){var c=FarmerQuests.catalog();assertEquals(24,c.definitions().size());assertTrue(c.definitions().values().stream().allMatch(d->d.profession()==Profession.FARMER));Set<String> done=new HashSet<>();for(var rank:List.of(ProfessionRank.APPRENTICE,ProfessionRank.JOURNEYMAN))for(int n=1;n<=8;n++)done.add(FarmerQuests.id(rank,n));assertFalse(c.mayAttempt(Profession.FARMER,FarmerQuests.id(ProfessionRank.MASTER,8),done));for(int n=1;n<=7;n++)done.add(FarmerQuests.id(ProfessionRank.MASTER,n));assertTrue(c.mayAttempt(Profession.FARMER,FarmerQuests.id(ProfessionRank.MASTER,8),done));}
 @Test void configurableQuantitiesRejectMissingUnknownAndFractionalValues()throws Exception{var path=dir.resolve("farmer.json");assertEquals(32,FarmerQuestRules.load(path).goal("a01"));String original=Files.readString(path);Files.writeString(path,original.replace("128","1.5"));assertThrows(java.io.IOException.class,()->FarmerQuestRules.load(path));Files.writeString(path,original.replace("\"a02\"","\"forged\""));assertThrows(java.io.IOException.class,()->FarmerQuestRules.load(path));}
 @Test void cropProvenanceSurvivesReloadAndIsRemovedExactlyOnce(){var data=new FarmerSavedData();var plant=new FarmerSavedData.Plant("minecraft:overworld",123,"minecraft:wheat",player);assertTrue(data.plant(plant));var restored=FarmerSavedData.load(data.save(new CompoundTag(),null),null);assertEquals(plant,restored.harvest("minecraft:overworld",123).orElseThrow());assertTrue(restored.harvest("minecraft:overworld",123).isEmpty());}
 @Test void sustainableCycleNeedsMatureHarvestThenSamePlayerAndBandReplantOnce(){var data=new FarmerSavedData();assertFalse(data.replant("minecraft:overworld",123,player,ProfessionRank.MASTER));data.awaitReplant("minecraft:overworld",123,player,ProfessionRank.MASTER);var restored=FarmerSavedData.load(data.save(new CompoundTag(),null),null);assertFalse(restored.replant("minecraft:overworld",123,UUID.randomUUID(),ProfessionRank.MASTER));assertFalse(restored.replant("minecraft:overworld",123,player,ProfessionRank.MASTER));restored.awaitReplant("minecraft:overworld",123,player,ProfessionRank.MASTER);assertTrue(restored.replant("minecraft:overworld",123,player,ProfessionRank.MASTER));assertFalse(restored.replant("minecraft:overworld",123,player,ProfessionRank.MASTER));}
}
